{
  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C15"],
      "claim": "A 6-methoxyindole hybrid with a methyl group and polar pyridyl-enone side chain reached brain concentrations approximating plasma in mice, demonstrating that this methoxyindole core readily crosses the BBB.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C31"],
      "claim": "MOMIPP, a closely related 6-methoxy-2-methylindole with a pyridyl-enone substituent, maintained brain/plasma ratios of 50–60% for 8 h in mice, supporting CNS access for the methoxyindole scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C12"],
      "claim": "O-methylbufotenine, a 5-methoxyindole with a basic dimethylaminoethyl side chain, showed brain/blood ratios >1 in mice, indicating robust brain uptake despite a basic amine.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C24"],
      "claim": "Human PET with 11C-melatonin confirmed that a 5-methoxyindole can readily cross the human BBB, supporting transfer of methoxyindole CNS penetration to the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C32"],
      "claim": "Ellipticine, a fused indole-pyridine carbazole with methyl groups, showed relatively high brain accumulation in mice due to lipophilicity and low molecular weight, supporting CNS access for the aromatic fused indole-pyridine system.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C23"],
      "claim": "Flortaucipir, a pyridoindole tau PET tracer, demonstrated good brain uptake in humans, showing that fused indole-pyridine heteroaromatics can achieve meaningful CNS exposure.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "6-MeO-THBC, a tetrahydro-beta-carboline with the same 6-methoxyindole motif, penetrated the BBB poorly in mice; however, its saturated, more basic tetrahydropyridine ring differs from the fully aromatic, less basic pyridine ring of the query.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C20"],
      "claim": "A 2,3-diarylindole bearing a sulfonamide showed very low brain uptake despite lipophilicity, but the polar sulfonamide and larger molecular size are not shared by the query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Pass: multiple methoxyindole and fused indole-pyridine analogues with direct BBB-penetration evidence support meaningful CNS access for 6-methoxyharmane; the closest contradictory tetrahydro-beta-carboline is less transferable because of its saturated basic ring.",
  "evidence_gaps": [
    "No direct brain/plasma or CSF measurement for 6-methoxyharmane itself.",
    "No human PET or efflux-transporter data for the query.",
    "The closest beta-carboline analogue (6-MeO-THBC) is saturated and more basic, limiting direct transfer."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

